class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        def ok(m):
            c, i = 0, 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                c += (j - i) // (m + 1)
                i = j
            return c <= numOps
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

