class Solution {
    public int minLength(String s, int numOps) {
        int n = s.length(), lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(s, numOps, mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    private boolean ok(String s, int numOps, int m) {
        int n = s.length();
        long c = 0;
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            c += (j - i) / (m + 1);
            i = j;
        }
        return c <= numOps;
    }
}

