var minLength = function(s, numOps) {
    const n = s.length;
    const ok = (m) => {
        let c = 0;
        for (let i = 0; i < n;) {
            let j = i;
            while (j < n && s[j] === s[i]) j++;
            c += Math.floor((j - i) / (m + 1));
            i = j;
        }
        return c <= numOps;
    };
    let lo = 1, hi = n;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ok(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
};

